/bin/bash -lc 'GOAI_WS="$GOAI_WORKSPACE" .venv/bin/python - <<'"'PY'
import json, os, re
p=os.environ['GOAI_WS']+'/library/papers.jsonl'
for i,l in enumerate(open(p),1):
 try:r=json.loads(l)
 except: continue
 t=(r.get('title') or '')
 if re.search(r'phase|thermod|CALPHAD|silicate|ZnO|SiO2|oxide|metastab|synthesis',t,re.I):
  print(i, r.get('year'), r.get('citation_count',0), t, r.get('doi') or r.get('arxiv_id') or r.get('id'))
PY"

